function storyIllustration(index, page) {
	const story = stories[index];
	const panel = storyPageMaps[index][page - 1];
	if (page === 0 || panel === -1) return {
		image: story.image,
		alt: story.imageAlt
	};
	return storyPictures[index][panel ?? 2];
}
